(() => {
  const Analytics={track(event,gameId,params={}){const detail={gameId,...params};if(window.TelePlayGameShell?.emit)window.TelePlayGameShell.emit(event,detail);else{window.TelePlayCore?.PlayerData?.handleEvent?.(event,gameId,params);const payload={event,at:Date.now(),...detail};window.dispatchEvent(new CustomEvent(`teleplay:${event}`,{detail:payload}));window.dataLayer?.push(payload)}},gameOpened:gameId=>Analytics.track('game_opened',gameId),gameStarted:gameId=>Analytics.track('game_started',gameId),gameFinished:(gameId,params)=>Analytics.track('game_finished',gameId,params),gameRestarted:gameId=>Analytics.track('game_restarted',gameId),gamePaused:gameId=>Analytics.track('game_paused',gameId),newRecord:(gameId,params)=>Analytics.track('new_record',gameId,params),coinsEarned:(gameId,params)=>Analytics.track('coins_earned',gameId,params),levelCompleted:(gameId,params)=>Analytics.track('level_completed',gameId,params)};
  window.TelePlayCore??={};window.TelePlayCore.Analytics=Analytics;
})();
